solution:
class ConfigError(Exception):
    pass


def load_port(config):
    try:
        value = config["port"]
        if isinstance(value, bool) or not isinstance(value, (int, str)):
            raise TypeError("порт должен быть целым числом или строкой")
        port = int(value)
        if not 1 <= port <= 65535:
            raise ValueError("порт вне диапазона")
        return port
    except (KeyError, TypeError, ValueError) as exc:
        raise ConfigError("не указан корректный порт") from exc


def load_port_result(config):
    try:
        return ("ok", load_port(config))
    except ConfigError as exc:
        return ("error", type(exc).__name__, str(exc), type(exc.__cause__).__name__)

