_END = object()

def merge_sorted(a, b):
    it_a, it_b = iter(a), iter(b)
    x = next(it_a, _END)
    y = next(it_b, _END)
    while x is not _END or y is not _END:
        if y is _END or (x is not _END and x <= y):
            yield x
            x = next(it_a, _END)
        else:
            yield y
            y = next(it_b, _END)

